<script setup lang="ts">
import FileUpload from '~/components/Shared/FileUpload.vue'
import { canViewProjectSection, projectMemberRoleName } from '~~/shared/utils/project-permissions'
import { useQuery, useQueryClient } from '@tanstack/vue-query'
import type { Project } from '~~/shared/types/projects'
import { projectProfile, projectProfileSchema, projectStatuses } from '~~/shared/utils/project-workspace'
import type { TeamUnit } from '~~/shared/types/team'
const props=defineProps<{project:Project}>()
const emit=defineEmits<{settings:[]}>()
const auth=useAuthStore(),client=useQueryClient(),busy=ref(false),error=ref(''),editing=ref(false),activity=ref('all')
const form=reactive(projectProfile(props.project))
watch(()=>props.project, p=>{if(!editing.value)Object.assign(form,projectProfile(p))})
const profile=computed(()=>projectProfile(props.project))
const units=useQuery({queryKey:computed(()=>['account',auth.user?.id,'project-team-units']),queryFn:()=>sharedRequest<TeamUnit[]>('/api/projects/units'),retry:false})
const roles=computed(()=>[{label:'Все сферы деятельности',value:'all'},...(units.data.value??[]).map(u=>({label:u.name,value:u.id}))])
function matchesActivity(ids:string[]=[]){return ids.some(id=>{const seen=new Set<string>();let current:string|undefined=id;while(current&&!seen.has(current)){if(current===activity.value)return true;seen.add(current);current=units.data.value?.find(u=>u.id===current)?.parentId||undefined}return false})}
const members=computed(()=>props.project.members.filter(m=>m.permission!=='hidden'&&(activity.value==='all'||matchesActivity(m.roleIds))))
const canEdit=computed(()=>props.project.permission!=='viewer')
async function action(action:string,data:unknown){busy.value=true;error.value='';try{await sharedRequest(`/api/projects/${props.project.id}/workspace`,{method:'POST',body:{action,data,...(action==='favorite'?{}:{revision:props.project.revision})}});await client.invalidateQueries({queryKey:['account',auth.user?.id,'projects']});editing.value=false}catch(e:any){error.value=e?.data?.message||'Не удалось сохранить';}finally{busy.value=false}}
function save(){const result=projectProfileSchema.safeParse(form);if(!result.success){error.value=result.error.issues[0]?.message||'Проверьте поля';return}void action('profile',result.data)}
async function avatar(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>500000){error.value='Выберите PNG, JPEG или WebP до 500 КБ';return}const reader=new FileReader();reader.onload=()=>{form.avatar=String(reader.result)};reader.readAsDataURL(file)}
const date=(v:string)=>v?new Intl.DateTimeFormat('ru-RU',{dateStyle:'medium'}).format(new Date(v+'T12:00:00')):'Не указана'
</script>
<template>
 <section class="project-summary">
  <UAlert v-if="error" color="error" :description="error"/>
  <header class="summary-top"><img v-if="profile.avatar" :src="profile.avatar" alt="Аватар проекта"/><span v-else class="summary-avatar"><UIcon name="i-lucide-folder-kanban"/></span><div><h2>{{project.name}}</h2><UBadge color="neutral" variant="soft">{{projectStatuses.find(s=>s.value===profile.status)?.label}}</UBadge><UBadge v-if="profile.archived" color="neutral">В архиве</UBadge></div><UButton :icon="project.favorite?'i-lucide-star-off':'i-lucide-star'" :label="project.favorite?'В избранном':'В избранное'" color="neutral" variant="outline" :loading="busy" @click="action('favorite',{favorite:!project.favorite})"/><UButton v-if="canEdit" label="Редактировать обзор" icon="i-lucide-pencil" color="neutral" variant="outline" @click="Object.assign(form,profile);editing=true"/></header>
  <div class="summary-facts"><div><small>Дата начала</small><strong>{{date(profile.startOn)}}</strong></div><div><small>Дата окончания</small><strong>{{date(profile.endOn)}}</strong></div><div><small>Менеджер проекта</small><strong>{{project.members.find(m=>m.userId===profile.managerId)?.fullName||'Не назначен'}}</strong></div><NuxtLink v-if="canViewProjectSection(project, 'tasks')" :to="`/projects/${project.id}/tasks`"><small>Количество задач</small><strong>{{project.taskCount??0}}</strong></NuxtLink></div>
  <article class="summary-panel"><h3>Описание проекта</h3><p class="summary-description">{{profile.description||'Описание пока не добавлено.'}}</p></article>
  <article class="summary-panel"><div class="summary-team-heading"><h3>Участники и наблюдатели</h3><USelect v-model="activity" :items="roles" aria-label="Сфера деятельности"/><UButton v-if="project.canManageMembers" label="Управлять участниками" icon="i-lucide-user-plus" color="neutral" variant="outline" @click="emit('settings')"/></div><div class="summary-members"><div v-for="m in members" :key="m.userId"><SharedPersonAvatar :name="m.fullName||m.email"/><NuxtLink :to="`/team/${m.userId}`">{{m.fullName||m.email}}<small>{{ projectMemberRoleName(project, m) }}</small></NuxtLink></div><p v-if="!members.length">По выбранной сфере участников нет.</p></div></article>
  <div class="summary-links"><NuxtLink :to="`/projects/${project.id}/chats`"><UIcon name="i-lucide-messages-square"/><strong>Чаты проекта</strong><span>Обсуждения, вложения и пароли →</span></NuxtLink><NuxtLink :to="`/projects/${project.id}/passwords`"><UIcon name="i-lucide-key-round"/><strong>Пароли проекта</strong><span>Доступы к сервисам для участников →</span></NuxtLink><NuxtLink v-if="canViewProjectSection(project, 'documents')" :to="`/projects/${project.id}/documents`"><UIcon name="i-lucide-folder-open"/><strong>Документы проекта</strong><span>Файлы, редакторы и доступ участников →</span></NuxtLink><NuxtLink v-if="canViewProjectSection(project, 'tasks')" :to="`/projects/${project.id}/tasks`"><UIcon name="i-lucide-columns-3"/><strong>Задачи</strong><span>Кабан проекта →</span></NuxtLink><NuxtLink v-if="canViewProjectSection(project, 'economy')" :to="`/projects/${project.id}/economy`"><UIcon name="i-lucide-chart-no-axes-combined"/><strong>Экономика проекта</strong><span>Смета, документы и этапы →</span></NuxtLink></div>
 </section>
 <UModal v-model:open="editing" title="Обзор проекта" :dismissible="!busy"><template #body><form class="space-y-4" @submit.prevent="save"><UFormField label="Название"><UInput v-model="form.name" required :maxlength="120" class="w-full"/></UFormField><UFormField label="Аватар проекта (до 500 КБ)"><FileUpload label="Выбрать аватар проекта" hint="PNG, JPEG или WebP до 500 КБ" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="avatar"/><img v-if="form.avatar" :src="form.avatar" alt="Предпросмотр" width="64"/><UButton v-if="form.avatar" label="Убрать аватар" color="neutral" variant="ghost" @click="form.avatar=''"/></UFormField><UFormField label="Статус"><USelect v-model="form.status" :items="projectStatuses" class="w-full"/></UFormField><UFormField label="Дата начала"><SharedDatePicker v-model="form.startOn" class="w-full"/></UFormField><UFormField label="Дата окончания"><SharedDatePicker v-model="form.endOn" :min="form.startOn||undefined" class="w-full"/></UFormField><UFormField label="Описание"><UTextarea v-model="form.description" :maxlength="20000" class="w-full"/></UFormField><UFormField label="Менеджер"><USelect v-model="form.managerId" :items="[{label:'Не назначен',value:''},...project.members.filter(m=>m.hasAccess&&m.permission!=='hidden').map(m=>({label:m.fullName||m.email,value:m.userId}))]" class="w-full"/></UFormField><UAlert v-if="error" color="error" :description="error"/><UButton type="submit" label="Сохранить" :loading="busy"/></form></template></UModal>
</template>
<style scoped>
.project-summary{display:grid;gap:24px}.summary-top{display:flex;align-items:center;gap:18px;flex-wrap:wrap}.summary-top>div{flex:1}.summary-top h2{font-size:26px;margin-bottom:10px}.summary-top img,.summary-avatar{width:80px;height:80px;border-radius:22px;object-fit:cover}.summary-avatar{display:grid;place-items:center;background:#e9edf4;font-size:36px}.summary-facts{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.summary-facts>*,.summary-panel,.summary-links>a{border:1px solid #e2e8f0;border-radius:20px;padding:24px;background:#fff}.summary-facts small{display:block;color:#94a3b8;margin-bottom:12px}.summary-facts strong{font-size:18px}.summary-panel h3{font-weight:600;font-size:18px}.summary-description{white-space:pre-wrap;overflow-wrap:anywhere;color:#64748b;margin-top:16px}.summary-team-heading{display:flex;align-items:center;gap:16px;flex-wrap:wrap}.summary-team-heading h3{flex:1}.summary-members{display:grid;gap:18px;margin-top:24px}.summary-members>div{display:flex;align-items:center;gap:12px}.summary-members a{flex:1}.summary-members small{display:block;color:#94a3b8;margin-top:4px}.summary-links{display:grid;grid-template-columns:1fr 1fr;gap:20px}.summary-links>a{display:flex;flex-direction:column;gap:14px}.summary-links .iconify{font-size:28px}.summary-links span{color:#8292a8}@media(max-width:750px){.summary-facts{grid-template-columns:1fr 1fr}.summary-links{grid-template-columns:1fr}.summary-members>div{flex-wrap:wrap}}
</style>
